def render_safe(text: str) -> str:
    try:
        return text.upper()
    except Exception:
        return text

def _render_evidence(where: layout.Layout, approved: workspace.Approved, current: str) -> str:
    results = workspace.load_results(where, approved, current, (plan.TRAIN, plan.VAL))
    cases = [c for c in approved.cases if approved.splits[c.id] != plan.TEST]
    parts = [evidence.render_case(where, approved.model, c, plan.TRAIN, [r for r in results if r.case_id == c.id]) for c in cases]
    return "\n".join(parts)

def _evaluate_check(where: layout.Layout, case: plan.Case, check: plan.Check, sandbox: Path, response: str) -> checks.Outcome:
    if check.kind == "command":
        result = proc.run_command(check.run, where.root, COMMAND_TIMEOUT_SEC)
        return checks.evaluate_command(result.code, result.tail)
    return checks.evaluate_text_check(check.kind, response, check.value, case.expected)
